const VT_X=(x,y,s,col,w=6)=>VT_L(x-s,y-s,x+s,y+s,col,w)+VT_L(x-s,y+s,x+s,y-s,col,w);
const VT_tick=(x,y,s,col)=>`<polyline points="${x-s},${y} ${x-s*.3},${y+s*.7} ${x+s},${y-s*.7}" fill="none" stroke="${col}" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>`;
