const VT_SUB=b=>`<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
/* a NAND gate symbol: body from (x,y) of width w and height h, bubble on the right; returns the output x */
const VT_nand=(x,y,w,h,col='#18213A',fill='#FFFFFF',sw=3)=>{const r=h/2,bx=x+w-r;return `<path d="M${x},${y} H${bx} A${r},${r} 0 0 1 ${bx},${y+h} H${x} Z" fill="${fill}" stroke="${col}" stroke-width="${sw}"/><circle cx="${x+w+7}" cy="${y+r}" r="7" fill="#FFFFFF" stroke="${col}" stroke-width="${sw}"/>`};
const VT_and=(x,y,w,h,col='#18213A',fill='#FFFFFF',sw=3)=>{const r=h/2,bx=x+w-r;return `<path d="M${x},${y} H${bx} A${r},${r} 0 0 1 ${bx},${y+h} H${x} Z" fill="${fill}" stroke="${col}" stroke-width="${sw}"/>`};
/* the three-NAND circuit Z = A·(B + C) with good/faulty values; v = {a,b,c,g1,g2,z} strings, hl = colour of the difference path */
